@CrossOrigin
@RestController
@RequestMapping("/SubscriberQuery")
public class SubscriberQueryRestController extends BaseSpringRestController {
	
	public SubscriberQueryRestController( SubscriberService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Subscriber using a UUID
     * @param		UUID subscriberId
     * @return		Subscriber
     */    
    @GetMapping("/load")
    public Subscriber load( @RequestParam(required=true) UUID subscriberId ) {
    	Subscriber entity = null;

    	try {  
    		entity = service.getSubscriber( new SubscriberFetchOneSummary( subscriberId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Subscriber using Id " + subscriberId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Subscriber business objects
     * @return		Set<Subscriber>
     */
    @GetMapping("/")
    public List<Subscriber> loadAll() {                
    	List<Subscriber> subscriberList = null;
        
    	try {
            // load the Subscriber
            subscriberList = service.getAllSubscriber();
            
            if ( subscriberList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Subscribers" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Subscribers ", exc );
        	return null;
        }

        return subscriberList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Subscriber subscriber = null;
    protected SubscriberService service = null;
    private static final Logger LOGGER = Logger.getLogger(SubscriberQueryRestController.class.getName());
    
}
